class Solution {
public:
    int maximumScore(vector<int>& nums, int k) {
        int n = nums.size();
        int i = k, j = k;
        int minVal = nums[k];
        long long ans = nums[k];
        while (i > 0 || j < n - 1) {
            if (i == 0) {
                j++;
                minVal = min(minVal, nums[j]);
            } else if (j == n - 1) {
                i--;
                minVal = min(minVal, nums[i]);
            } else if (nums[i - 1] > nums[j + 1]) {
                i--;
                minVal = min(minVal, nums[i]);
            } else {
                j++;
                minVal = min(minVal, nums[j]);
            }
            ans = max(ans, (long long)minVal * (j - i + 1));
        }
        return (int)ans;
    }
};
